import SwiftUI

public struct FLXCollapsibleStyle: DisclosureGroupStyle {
    public init() {}

    public func makeBody(configuration: Configuration) -> some View {
        FLXCollapsibleStyleBody(configuration: configuration)
    }
}

private struct FLXCollapsibleStyleBody: View {
    @Environment(\.flxTheme) private var theme
    @Environment(\.isEnabled) private var isEnabled
    @ScaledMetric(relativeTo: .body) private var scale: CGFloat = 1

    let configuration: FLXCollapsibleStyle.Configuration

    var body: some View {
        VStack(alignment: .leading, spacing: FLXSpacing.sm) {
            Button {
                withAnimation(.easeInOut(duration: 0.2)) {
                    configuration.isExpanded.toggle()
                }
            } label: {
                HStack(spacing: FLXSpacing.sm) {
                    configuration.label
                        .flxFont(.headline)
                        .foregroundStyle(theme.colors.foreground)
                    Spacer()
                    Image(systemName: "chevron.up.chevron.down")
                        .font(.system(size: FLXCollapsibleMetrics.iconSize * scale, weight: .medium))
                        .foregroundStyle(theme.colors.mutedForeground)
                        .frame(width: triggerHeight, height: triggerHeight)
                }
                .contentShape(Rectangle())
            }
            .buttonStyle(.plain)

            if configuration.isExpanded {
                configuration.content
                    .transition(.opacity.combined(with: .move(edge: .top)))
            }
        }
        .opacity(isEnabled ? 1 : FLXOpacity.disabled)
    }

    private var triggerHeight: CGFloat {
        FLXCollapsibleMetrics.triggerHeight * scale
    }
}

struct AnyFLXCollapsibleStyle: DisclosureGroupStyle {
    private let _makeBody: (Configuration) -> AnyView

    init<S: DisclosureGroupStyle>(_ style: S) {
        _makeBody = { AnyView(style.makeBody(configuration: $0)) }
    }

    func makeBody(configuration: Configuration) -> some View {
        _makeBody(configuration)
    }
}

private struct FLXCollapsibleStyleOverrideKey: EnvironmentKey {
    static let defaultValue: AnyFLXCollapsibleStyle? = nil
}

extension EnvironmentValues {
    var flxCollapsibleStyleOverride: AnyFLXCollapsibleStyle? {
        get { self[FLXCollapsibleStyleOverrideKey.self] }
        set { self[FLXCollapsibleStyleOverrideKey.self] = newValue }
    }
}

extension View {
    public func flxCollapsibleStyle<S: DisclosureGroupStyle>(_ style: S) -> some View {
        environment(\.flxCollapsibleStyleOverride, AnyFLXCollapsibleStyle(style))
    }
}

private enum FLXCollapsibleMetrics {
    static let iconSize: CGFloat = 14
    static let triggerHeight: CGFloat = 32
}

import SwiftUI

public struct FLXCollapsible<Label: View, Content: View>: View {
    @Environment(\.flxCollapsibleStyleOverride) private var styleOverride
    @State private var internalIsExpanded: Bool
    private let externalIsExpanded: Binding<Bool>?
    private let content: () -> Content
    private let label: () -> Label

    /// `isExpanded` is optional: pass a `Binding` to control the state from outside
    /// (mirrors Radix's `open`/`onOpenChange`), or omit it to let the component
    /// manage its own state internally (mirrors Radix's uncontrolled default).
    /// `DisclosureGroup` itself doesn't expose this duality via a single initializer,
    /// so this is a deliberate deviation from copying its init surface 1:1 — see
    /// DESIGN_SYSTEM.md section 3, "if the pattern doesn't fit".
    public init(
        isExpanded: Binding<Bool>? = nil,
        @ViewBuilder content: @escaping () -> Content,
        @ViewBuilder label: @escaping () -> Label
    ) {
        self.externalIsExpanded = isExpanded
        self._internalIsExpanded = State(initialValue: isExpanded?.wrappedValue ?? false)
        self.content = content
        self.label = label
    }

    private var isExpanded: Binding<Bool> {
        externalIsExpanded ?? $internalIsExpanded
    }

    public var body: some View {
        DisclosureGroup(isExpanded: isExpanded, content: content, label: label)
            .disclosureGroupStyle(styleOverride ?? AnyFLXCollapsibleStyle(FLXCollapsibleStyle()))
    }
}

extension FLXCollapsible where Label == Text {
    public init(
        _ titleKey: LocalizedStringKey,
        isExpanded: Binding<Bool>? = nil,
        @ViewBuilder content: @escaping () -> Content
    ) {
        self.init(isExpanded: isExpanded, content: content) {
            Text(titleKey)
        }
    }

    @_disfavoredOverload
    public init(
        _ titleResource: LocalizedStringResource,
        isExpanded: Binding<Bool>? = nil,
        @ViewBuilder content: @escaping () -> Content
    ) {
        self.init(isExpanded: isExpanded, content: content) {
            Text(titleResource)
        }
    }

    @_disfavoredOverload
    public init<S: StringProtocol>(
        _ title: S,
        isExpanded: Binding<Bool>? = nil,
        @ViewBuilder content: @escaping () -> Content
    ) {
        self.init(isExpanded: isExpanded, content: content) {
            Text(title)
        }
    }
}
